async function api(request, env) {
  const url = new URL(request.url);
  const adminResponse = await adminApi(request, env);
  if (adminResponse) return adminResponse;
  const ownerAccess = await isOwner(request, env);
  const photoResponse = await photosApi(request, env, ownerAccess);
  if (photoResponse) return photoResponse;
  const schoolResponse = await schoolsApi(request, env, ownerAccess);
  if (schoolResponse) return schoolResponse;
  if (url.pathname === "/api/me") return json3({ owner: ownerAccess, signedIn: ownerAccess || !!request.headers.get("oai-authenticated-user-id"), passwordAuth: passwordAuth(env), testing: env.TESTING_MODE === "true", configured: !!env.BUCKET && (env.TESTING_MODE === "true" || passwordAuth(env) || !!env.ADMIN_EMAIL) });
  if (!env.BUCKET) return json3({ error: "Cloud storage unavailable" }, 503);
  if (url.pathname === "/api/state") {
    if (!ownerAccess) return json3({ error: "Owner sign-in required" }, 403);
    if (request.method === "GET") {
      const obj = await env.BUCKET.get(KEY);
      return json3(obj ? { state: await obj.json(), revision: obj.etag } : { state: null, revision: null });
    }
    if (request.method === "PUT") {
      if (request.headers.get("Origin") !== url.origin) return json3({ error: "Origin mismatch" }, 403);
      if (Number(request.headers.get("Content-Length") || 0) > 8e6) return json3({ error: "Data too large" }, 413);
      let payload;
      try {
        const raw = await request.text();
        if (raw.length > 8e6) return json3({ error: "Data too large" }, 413);
        payload = JSON.parse(raw);
        validate(payload.state);
      } catch {
        return json3({ error: "Invalid examination data" }, 400);
      }
      const existing = await env.BUCKET.head(KEY);
      let auditPrevious = null;
      if (!existing) {
        payload.state.schools = [];
        payload.state.schoolSubmissions = [];
        payload.state.schoolEditRequests = [];
        try {
          assertChangedSeatRules(payload.state, { rooms: [], students: [] });
        } catch {
          return json3({ error: "School/class adjacency conflict." }, 400);
        }
      }
      if ((existing?.etag || null) !== (payload.revision || null)) return json3({ error: "Data changed on another device. Reload cloud data before saving." }, 409);
      if (existing) {
        const previous = await env.BUCKET.get(KEY);
        if (previous?.etag !== existing.etag) return json3({ error: "Concurrent update. Reload cloud data." }, 409);
        const old = await previous.json();
        auditPrevious = old;
        payload.state.schools = old.schools || [];
        payload.state.schoolSubmissions = old.schoolSubmissions || [];
        payload.state.schoolEditRequests = old.schoolEditRequests || [];
        const priorStudents = new Map(old.students.map((s) => [s.id, s]));
        for (const student of payload.state.students) {
          const prior = priorStudents.get(student.id);
          if (!prior || ["name", "grade", "fatherName", "guardianName", "guardianPhone"].some((k) => (student[k] || "") !== (prior[k] || ""))) {
            try {
              Object.assign(student, validatedStudent(student, { exam: payload.state.exam }));
            } catch (e) {
              return json3({ error: e.message, fieldErrors: e.fieldErrors }, 400);
            }
          }
          if (!prior || student.schoolId !== prior.schoolId || student.school !== prior.school) {
            const school = registeredSchool(old, student.schoolId);
            if (!school) return json3({ error: "Select an active registered school.", fieldErrors: { schoolId: "Register this school on the Schools page first." } }, 400);
            student.school = school.name;
          }
        }
        try {
          assertChangedSeatRules(payload.state, old);
        } catch {
          return json3({ error: "School/class adjacency conflict. Rebuild the affected room." }, 400);
        }
        const priorTokens = new Map(old.students.map((s) => [s.id, s.qrToken]));
        if (payload.state.students.some((s) => priorTokens.has(s.id) && priorTokens.get(s.id) !== s.qrToken)) return json3({ error: "Permanent QR tokens cannot change. Restore a backup with matching tokens." }, 400);
      }
      appendAudit(payload.state, auditPrevious, { type: "admin", label: env.TESTING_MODE === "true" ? "Admin (local preview)" : "Admin (shared account)" });
      const result = await env.BUCKET.put(KEY, JSON.stringify(payload.state), { httpMetadata: { contentType: "application/json" }, onlyIf: existing ? { etagMatches: existing.etag } : { etagDoesNotMatch: "*" } });
      if (!result) return json3({ error: "Concurrent update. Reload cloud data." }, 409);
      return json3({ revision: result.etag });
    }
    return json3({ error: "Method not allowed" }, 405);
  }
  if (url.pathname === "/api/volunteer/seat" || url.pathname.startsWith("/api/seat/")) {
    if (request.method !== "GET") return json3({ error: "Method not allowed" }, 405);
    const byRoll = url.pathname === "/api/volunteer/seat";
    const value = byRoll ? normalizedDigits(url.searchParams.get("roll") || "") : url.pathname.slice("/api/seat/".length);
    if (byRoll ? !/^[0-9]{1,30}$/.test(value) : !/^[a-zA-Z0-9_-]{20,100}$/.test(value)) return json3({ error: byRoll ? "Enter a valid exam roll." : "Invalid QR" }, 400);
    const obj = await env.BUCKET.get(KEY);
    if (!obj) return json3({ error: "The seating plan has not been published yet." }, 404);
    const data = await obj.json();
    const student = data.students.find((s) => byRoll ? normalizedDigits(s.roll) === value : s.qrToken === value);
    if (!student) return json3({ error: "Roll not found." }, 404);
    const r = data.rooms.find((r2) => r2.id === student.seat?.roomId);
    const counts = r?.columnBenches;
    const validCounts = Array.isArray(counts) && counts.length <= 6 && counts.every((n) => Number.isInteger(n) && n > 0) && counts.reduce((a, b) => a + b, 0) === r.benches;
    return json3({ v: 2, live: true, roll: student.roll, exam: { name: data.exam.name, center: data.exam.center, date: data.exam.date, time: data.exam.time }, seat: r ? { ...student.seat, room: r.name, building: r.building, floor: r.floor, directions: r.directions } : null, layout: r ? { benches: r.benches, per: r.per, columns: validCounts ? counts.length : r.mapColumns, columnBenches: validCounts ? counts : null } : null });
  }
  return json3({ error: "Not found" }, 404);
}


